from functools import wraps

def rate_limit(leak_rate, capacity, clock):
    def decorator(func):
        water = 0
        last_leak = clock()

        @wraps(func)
        def limited(*args, **kwargs):
            nonlocal water, last_leak
            now = clock()
            water = max(0, water - (now - last_leak) * leak_rate)
            last_leak = now
            if water + 1 <= capacity:
                water += 1
                return func(*args, **kwargs)
            return False

        return limited

    return decorator

